<script>
(()=>{const menu=document.getElementById('adminMenu'),open=document.getElementById('adminMenuButton'),close=document.getElementById('adminMenuClose');function set(show){menu.classList.toggle('open',show);document.body.style.overflow=show?'hidden':''}open.onclick=()=>set(true);close.onclick=()=>set(false);menu.addEventListener('click',e=>{if(e.target===menu)set(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')set(false)})})();
(()=>{const input=document.getElementById('adminFindAnything'),box=document.getElementById('adminSearchResults');if(!input||!box)return;let timer,controller;const esc=s=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));function close(){box.classList.remove('open')}input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();if(!q){close();return}timer=setTimeout(async()=>{controller?.abort();controller=new AbortController();try{const r=await fetch('<?=$base?>/api/work/admin_search.php?q='+encodeURIComponent(q)+'&job_id=<?=$adminJobId?>',{signal:controller.signal});const d=await r.json(),rows=d.results||[];box.innerHTML=rows.length?rows.map(x=>`<a href="${esc(x.url)}"><strong>${esc(x.title)}</strong><small>${esc(x.description||x.type||'')}</small></a>`).join(''):'<div class="admin-search-empty">No matches.</div>';box.classList.add('open')}catch(e){}},180)});document.addEventListener('click',e=>{if(!e.target.closest('.admin-search-wrap'))close()})})();
</script>
